import AbstractExpressGateway from './AbstractExpressGateway';

class AmazonPayGateway extends AbstractExpressGateway {

    type = 'amazonPay';

    constructor(props) {
        super(props);
        this.capabilities = [
            ...this.capabilities,
            'form_validation',
            'confirmation_token'
        ];
    }

}

export default AmazonPayGateway;